<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';$pdo=aep_database();$clients=$pdo->query('SELECT id,name,client_reference FROM clients ORDER BY name')->fetchAll();$error='';
require_once __DIR__ . '/legal_library.php';
if($_SERVER['REQUEST_METHOD']==='POST'){aep_validate_csrf();$clientId=(int)($_POST['client_id']??0);$practice=aep_post_string('practice_area',100);$subject=aep_post_string('subject',300);if(!$clientId||$practice===''||$subject===''){$error='Client, practice area, and subject are required.';}else{$check=$pdo->prepare('SELECT 1 FROM clients WHERE id=?');$check->execute([$clientId]);if(!$check->fetch()){$error='Select a valid client.';}else{$ref=aep_reference('MAT');$pdo->prepare('INSERT INTO matters(matter_reference,client_id,practice_area,subject,status)VALUES(?,?,?,?,?)')->execute([$ref,$clientId,$practice,$subject,aep_valid_status(aep_post_string('status',20),['open','active','closed'],'open')]);$newId=(int)$pdo->lastInsertId();aep_log_activity($pdo,'Matters','Created '.$ref,$newId);header('Location: matter_view.php?id='.$newId);exit;}}}
$pageTitle='Create Matter | AEP';$activeNav='matters';require __DIR__.'/includes/header.php';?>
<div class="card" style="max-width:820px;margin:auto"><h1>Create Matter</h1><?php if(!$clients):?><div class="empty">Create a client before opening a matter.<br><br><a class="btn" href="client_create.php">Create client</a></div><?php else:?><p class="muted">A matter links the client to legal work, tasks, deadlines, and Counsel Engine analysis.</p><?php if($error):?><p style="color:#b42318"><?php echo aep_h($error);?></p><?php endif;?><form class="grid grid-2" method="post" style="margin-top:18px"><?php echo aep_csrf_field();?><div><label>Client *</label><select name="client_id" required><option value="">Select client</option><?php foreach($clients as $client):?><option value="<?php echo (int)$client['id'];?>" <?php echo (int)($_POST['client_id']??$_GET['client_id']??0)===(int)$client['id']?'selected':'';?>><?php echo aep_h($client['name'].' — '.$client['client_reference']);?></option><?php endforeach;?></select></div><div><label>Practice area *</label><select name="practice_area" required><option value="">Select area</option><?php foreach(aep_domain_profiles() as $profile):?><option value="<?php echo aep_h($profile['label']);?>"><?php echo aep_h($profile['label']);?></option><?php endforeach;?></select></div><div><label>Subject *</label><input required name="subject" value="<?php echo aep_h($_POST['subject']??'');?>" placeholder="Short matter description"></div><div><label>Status</label><select name="status"><option value="open">Open</option><option value="active">Active</option><option value="closed">Closed</option></select></div><div class="actions"><button class="btn">Create matter</button><a class="btn secondary" href="matter_list.php">Cancel</a></div></form><?php endif;?></div><?php require __DIR__.'/includes/footer.php';?>
